def strategy(history, rng):
    if not history:
        return 'C'
    n = len(history)
    if n >= 99:
        return 'D'
    last_me, last_opp = history[-1]
    if n < 8:
        return 'C' if last_opp == 'C' else 'D'
    opp_c = 0
    my_c = 0
    for a, b in history:
        if a == 'C':
            my_c += 1
        if b == 'C':
            opp_c += 1
    recent = history[-12:] if n >= 12 else history
    recent_c = sum(1 for a, b in recent if b == 'C')
    opp_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_streak += 1
        else:
            break
    perceived = opp_c / n
    if last_opp == 'C' and last_me == 'D' and opp_c == n:
        return 'D'
    if recent_c == 0:
        if rng.random() < 0.04:
            return 'C'
        return 'D'
    if opp_c <= 3 and n >= 20:
        return 'D'
    if recent_c >= 11:
        if opp_c == n and last_opp == 'C' and last_me == 'C' and n >= 20:
            if rng.random() < 0.02:
                return 'D'
        return 'C'
    if perceived > 0.65:
        if last_opp == 'D':
            if last_me == 'C':
                return 'D'
            if opp_streak >= 5:
                return 'C' if rng.random() < 0.6 else 'D'
            if recent_c <= 9:
                return 'D' if rng.random() < 0.8 else 'C'
            if history[-2][1] == 'C' and rng.random() < 0.7:
                return 'D'
            return 'C'
        return 'C'
    if my_c / n > 0.75 and last_opp == 'D':
        return 'D'
    if n > 60 and opp_c > 35 and my_c < 30:
        return 'C'
    if last_opp == 'D':
        if last_me == 'D' and recent_c <= 6:
            if rng.random() < 0.08:
                return 'C'
            return 'D'
        if opp_streak >= 4 and perceived < 0.35:
            return 'D'
        if rng.random() < 0.12 + 0.25 * (recent_c / 12):
            return 'C'
        return 'D'
    if n % 10 == 9 and my_c > opp_c + 10:
        return 'D'
    if last_opp == 'C' and last_me == 'D' and perceived > 0.55 and recent_c >= 9:
        if rng.random() < 0.1:
            return 'D'
    if last_opp == 'C' and last_me == 'C' and my_c > opp_c + 10 and rng.random() < 0.03:
        return 'D'
    return 'C'
